def simple_math_problem() -> int:
    """Jill makes scented candles as a hobby. Her favorite scents are lavender, coconut, and almond, and she uses the same amount of each scent for every candle. This time, she made twice as many lavender candles as coconut candles, along with a batch of almond candles. She ran out of almond scent after making ten candles. If she had one and a half times as much coconut scent as almond scent and used all her coconut scent up too, how many lavender candles did she make?"""
    coconut_candles = 1.5 * 10
    lavender_candles = 2 * coconut_candles
    return int(lavender_candles)

def simple_math_problem() -> int:
    """Janice gave all three dozens of pebbles from her trip to her friends. Each of her friends got 4 pebbles. How many friends received pebbles?"""
    total_pebbles = 3 * 12
    pebbles_per_friend = 4
    total_friends = total_pebbles / pebbles_per_friend
    return int(total_friends)

def simple_math_problem() -> int:
    """Selena reads a book with 400 pages. Harry reads a book with 20 fewer than half the number of pages Selena's book has. How many pages are in the book of Harry?"""
    selena_pages = 400
    harry_pages = selena_pages / 2 - 20
    return int(harry_pages)

def simple_math_problem() -> int:
    """Lucy works in a pet shop. She can clean 2 aquariums in 3 hours. If Lucy is working 24 hours this week, how many aquariums could she clean?"""
    aquariums_per_hour = 2 / 3
    working_hours = 24
    aquariums = aquariums_per_hour * working_hours
    return int(aquariums)

def simple_math_problem() -> int:
    """Steve has 400 new emails in his inbox.  He moves half of them to the trash, and 40 percent of the remaining emails to his work folder.  How many emails are left in the inbox?"""
    emails = 400
    emails = emails / 2
    emails = emails * 0.6
    return int(emails)
